import com.fasterxml.jackson.databind.ObjectMapper

class Foo {
    fun toJson(obj: Any): String {
        return ObjectMapper().writeValueAsString(obj) // bad
    }
}

import com.fasterxml.jackson.databind.json.JsonMapper

class Foo {
    fun toJson(obj: Any): String {
        val mapper = JsonMapper.builder().build() // bad
        return mapper.writeValueAsString(obj)
    }
}

import com.fasterxml.jackson.databind.ObjectMapper

class Foo {
    companion object {
        private val MAPPER = ObjectMapper() // good - created once
    }
    fun toJson(obj: Any): String = MAPPER.writeValueAsString(obj)
}

import com.fasterxml.jackson.databind.ObjectMapper

class Foo {
    fun toJsonList(items: List<Any>): List<String> =
        items.map {
            ObjectMapper().writeValueAsString(it) // bad - created per lambda invocation
        }
}
